-- Work Pulse figures for one vendor at a time ('claude' or 'openai'), beside
-- the all-products figures in pulse_metrics, which are unchanged. Same columns
-- and meaning as pulse_metrics; written by the hourly aggregator only while
-- OpenAI data exists, so a Claude-only hub never fills it.
CREATE TABLE "pulse_metrics_vendor" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "pulse_metrics_vendor_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"vendor" text NOT NULL,
	"scope_type" text NOT NULL,
	"scope_id" text NOT NULL,
	"period_start" bigint NOT NULL,
	"period_end" bigint NOT NULL,
	"oti" double precision,
	"dds" double precision,
	"psr" double precision,
	"ors" double precision,
	"event_count" integer DEFAULT 0 NOT NULL,
	"tier_1_count" integer DEFAULT 0 NOT NULL,
	"tier_2_count" integer DEFAULT 0 NOT NULL,
	"tier_3_count" integer DEFAULT 0 NOT NULL,
	"computed_at" bigint NOT NULL,
	"granularity" text DEFAULT 'rolling' NOT NULL,
	"ors_breadth" double precision,
	"ors_overlap" double precision,
	"ors_propagation" double precision,
	"metric_version" integer DEFAULT 2 NOT NULL,
	"oti_early_read" integer DEFAULT 0 NOT NULL,
	"oti_active_days" integer
);
--> statement-breakpoint
CREATE UNIQUE INDEX "idx_pulse_metrics_vendor_week" ON "pulse_metrics_vendor" USING btree ("vendor","scope_type","scope_id","period_start") WHERE granularity = 'week';--> statement-breakpoint
CREATE INDEX "idx_pulse_metrics_vendor_scope" ON "pulse_metrics_vendor" USING btree ("vendor","scope_type","scope_id","period_end");
